845	async function resolveSkillFile(
846		requestPath: string,
847		skillMap: Map<string, Skill>,
848	): Promise<{ skillName: string; filePath: string }> {
849		const normalized = requestPath.replaceAll("\\", "/").replace(/^\/+|\/+$/g, "");
850		const segments = normalized.split("/").filter(Boolean);
851		if (!segments.length || segments.some(segment => segment === "." || segment === "..")) {
852			throw new Error("Skill 路径无效");
853		}
854		const skillName = segments.shift() ?? "";
855		const skill = skillMap.get(skillName);
856		if (!skill) throw new Error(`未知 Story Skill：${skillName}`);
857		const requested = segments.length ? path.resolve(skill.baseDir, ...segments) : skill.filePath;
858		const [realBase, realRequested] = await Promise.all([fs.realpath(skill.baseDir), fs.realpath(requested)]);
859		if (!isPathInside(realBase, realRequested)) throw new Error("Skill 路径越界");
860		const stat = await fs.stat(realRequested);
861		if (!stat.isFile()) throw new Error("Skill 路径不是文件");
862		return { skillName, filePath: realRequested };
863	}
