869		/\brm\s+-[a-zA-Z]*r[a-zA-Z]*f?[a-zA-Z]*\s+(--no-preserve-root\s+)?(\/\s*|\*?\s*$|~|\$HOME|\/\*)/,
870		/\bmkfs(?:\.[a-z0-9]+)?\b/i,
