878	function localShellInvocation(command: string): { file: string; args: string[] } {
879		if (!cachedLocalShell) {
880			if (process.platform === "win32") {
881				for (const candidate of ["bash.exe", "bash", "C:\\Program Files\\Git\\bin\\bash.exe"]) {
882					const probe = spawnSync(candidate, ["-lc", "true"], { stdio: "ignore", windowsHide: true });
883					if (!probe.error) {
884						cachedLocalShell = { file: candidate, args: ["-lc"] };
885						break;
886					}
887				}
888				cachedLocalShell ??= { file: process.env.COMSPEC || "cmd.exe", args: ["/d", "/s", "/c"] };
889			} else {
890				cachedLocalShell = { file: process.env.SHELL || "sh", args: ["-c"] };
891			}
892		}
893		return { file: cachedLocalShell.file, args: [...cachedLocalShell.args, command] };
894	}
