904	function capShellOutput(text: string): string {
905		return text.length > LOCAL_SHELL_MAX_OUTPUT_CHARS
906			? `…（输出过长，仅保留尾部 ${LOCAL_SHELL_MAX_OUTPUT_CHARS} 字符）\n${text.slice(-LOCAL_SHELL_MAX_OUTPUT_CHARS)}`
907			: text;
908	}
