910	function executeLocalShellCommand(
911		command: string,
912		cwd: string,
913		timeoutMs: number,
914		signal: AbortSignal | undefined,
915	): Promise<LocalShellResult> {
916		return new Promise((resolve, reject) => {
917			const invocation = localShellInvocation(command);
918			const child = spawn(invocation.file, invocation.args, {
919				cwd,
920				env: { ...process.env, STORY_WORKSPACE: cwd, STORY_SKILLS_DIR: skillsRoot },
921				windowsHide: true,
922			});
923			const startedAt = Date.now();
924			let stdout = "";
925			let stderr = "";
926			let settled = false;
927			let timedOut = false;
928			const timer = setTimeout(() => {
929				if (!settled) {
930					timedOut = true;
931					child.kill("SIGKILL");
932				}
933			}, timeoutMs);
934			const finish = (exitCode: number | null) => {
935				if (settled) return;
936				settled = true;
937				clearTimeout(timer);
938				signal?.removeEventListener("abort", onAbort);
939				resolve({ exitCode, stdout, stderr, durationMs: Date.now() - startedAt, timedOut });
940			};
941			const onAbort = () => child.kill("SIGKILL");
942			child.stdout?.on("data", (chunk) => {
943				if (stdout.length < LOCAL_SHELL_MAX_OUTPUT_CHARS * 2) stdout += chunk.toString();
944			});
945			child.stderr?.on("data", (chunk) => {
946				if (stderr.length < LOCAL_SHELL_MAX_OUTPUT_CHARS * 2) stderr += chunk.toString();
947			});
948			child.on("error", (error) => {
949				if (settled) return;
950				settled = true;
951				clearTimeout(timer);
952				signal?.removeEventListener("abort", onAbort);
953				reject(error);
954			});
955			child.on("close", (code) => finish(code));
956			signal?.addEventListener("abort", onAbort, { once: true });
957		});
958	}
