      storage: storeInfo(),
      agentRuntime: storyAgentRuntimeInfo(),
      skillReview: skillReviewPublicConfig(),
      email: emailConfig,
      authSession: {
        accessMinutes: authSessionConfig.accessTtlSeconds / 60,
        refreshDays: authSessionConfig.refreshTtlMs / (24 * 60 * 60 * 1000),
      },
    })
  } catch (error) {
    next(error)
