function frontmatterValue(source: string, key: string): string {
	const frontmatter = source.startsWith("---\n") ? source.slice(4, source.indexOf("\n---", 4)) : "";
	const match = new RegExp(`^${key}:\\s*(.+)$`, "m").exec(frontmatter);
	const value = match?.[1]?.trim() ?? "";
